'use strict';
// A runtime package that ships JS and NO declarations of its own — the
// `pg` shape. Its types live in the sibling @types/dtwin package, which is
// where the checker finds them and which used to be the package every
// diagnostic about this import named.
class Pool {
  constructor(size) {
    this.size = size;
  }
  describe() {
    return 'pool(' + this.size + ')';
  }
}
module.exports = { Pool };
